import {allItems,putItem,removeItem,getMeta,setMeta,putMany} from './db.js';
import {suggest} from './extract.mjs';
import {readImage} from './ocr.js';
const app=document.getElementById('app'),upload=document.getElementById('upload'),restore=document.getElementById('restore');
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const dayString=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>dayString(new Date());
const validDay=s=>{if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s+'T12:00:00Z');return !Number.isNaN(d.getTime())&&d.toISOString().slice(0,10)===s;};
const dateLabel=s=>s?new Date(`${s}T12:00:00`).toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'short'}):'날짜 미정';
const dateFull=s=>s?new Date(`${s}T12:00:00`).toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric'}):'날짜 미정';
const stamp=s=>new Date(s).toLocaleString('ko-KR',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
let items=[],worker=null,ocrRun=0,toastTimer;const urls=new Map(),pendingSaves=new Map(),saveFlights=new Map();
let state={mode:'calendar',view:'calendar',day:today(),month:today().slice(0,7),active:null,files:[],selected:new Set(),busy:false,progress:0,progressText:'',draft:null,query:'',filter:'전체',deleteConfirm:false,attachTarget:null};
function url(a){if(!urls.has(a.id))urls.set(a.id,URL.createObjectURL(a.blob));return urls.get(a.id);}
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function entry(i){return `<button class="entry" data-act="open" data-id="${E(i.id)}"><span class="entry-emoji ${['공연','혜택','책'].includes(i.category)?'peach':i.category==='채용'?'lavender':''}">${E(i.emoji)}</span><span class="entry-copy"><strong>${E(i.title)}</strong><small>${i.type==='event'?`${dateLabel(i.start)}${i.end!==i.start?' ~ '+dateLabel(i.end):''} · ${E(i.time||'시간 미정')}`:`${E(i.category)} · 스크린샷 ${i.attachments.length}장`}${i.sample?' · 예시':''}</small></span><span class="chevron" aria-hidden="true">›</span></button>`;}
function empty(s='아직 담긴 기억이 없어요.'){return `<div class="empty"><span class="empty-icon">🌱</span>${s}</div>`;}
function heading(s,more=''){return `<div class="section-heading"><h3>${s}</h3><span>${more}</span></div>`;}
function intro(title,sub,emoji=''){return `<div class="intro intro-row"><div><div class="eyebrow">LITTLE THINGS, WELL KEPT</div><h2>${title}</h2><p>${sub}</p></div>${emoji?`<span class="leaf">${emoji}</span>`:''}</div>`;}
function banner(){if(!items.length)return '<div class="sample-banner"><span>처음이라면 예시로 가볍게 둘러보세요.</span><button data-act="seed">예시 담기</button></div>';return items.some(i=>i.sample)?'<div class="sample-banner"><span>🌼 지금 보이는 예시는 가상의 내용이에요.</span><button data-act="clear-samples">예시 지우기</button></div>':'';}
function calendar(){const [y,m]=state.month.split('-').map(Number);const first=new Date(y,m-1,1),begin=new Date(y,m-1,1-first.getDay());let cells='';for(let n=0;n<42;n++){const d=new Date(begin);d.setDate(begin.getDate()+n);const ds=dayString(d);const ev=items.filter(i=>i.type==='event'&&i.start<=ds&&i.end>=ds);cells+=`<button class="day ${d.getMonth()!==m-1?'other':''} ${ds===state.day?'selected':''} ${ds===today()?'today':''}" data-act="day" data-day="${ds}" aria-label="${dateLabel(ds)}, 일정 ${ev.length}개" aria-pressed="${ds===state.day}"><span class="day-num">${d.getDate()}</span><span class="dots">${ev.slice(0,3).map(i=>`<i class="dot ${i.category==='채용'?'lavender':i.category==='공연'?'peach':''}"></i>`).join('')}</span></button>`;}
const selected=items.filter(i=>i.type==='event'&&i.start<=state.day&&i.end>=state.day).sort((a,b)=>a.time.localeCompare(b.time));return intro('기억이 일정이 되는 순간','가고 싶은 곳, 놓치고 싶지 않은 날을 담아요.','🌿')+banner()+`<div class="calendar-layout"><div class="card"><div class="calendar-head"><button data-act="month" data-delta="-1" aria-label="이전 달">‹</button><div><strong>${y}년 ${m}월</strong><button class="today" data-act="today">오늘</button></div><button data-act="month" data-delta="1" aria-label="다음 달">›</button></div><div class="weekdays">${['일','월','화','수','목','금','토'].map(s=>`<span>${s}</span>`).join('')}</div><div class="days">${cells}</div></div><div>${heading(dateLabel(state.day),'작은 약속들')}${selected.map(entry).join('')||empty('이날은 비어 있어요.<br>새로운 기억을 담아볼까요?')}<button class="secondary full" data-act="import">＋ 스크린샷으로 일정 담기</button></div></div>${heading('최근 담은 이야기','나의 페이지')}${items.filter(i=>i.type==='page').sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,3).map(entry).join('')||empty('책, 운동 팁, 장소 정보를 페이지로 모아요.')}<div class="footer">작은 기억을 오래, 담아</div>`;}
function home(){const events=items.filter(i=>i.type==='event'),pages=items.filter(i=>i.type==='page');const upcoming=events.filter(i=>i.end>=today()).sort((a,b)=>a.start.localeCompare(b.start)).slice(0,4);return intro('잘 모아둔 작은 것들','언젠가의 계획과 지금의 관심사를 한곳에.','🌼')+banner()+`<div class="shelves"><button class="shelf" data-act="calendar"><span class="shelf-icon">🗓️</span><strong>캘린더</strong><small>${events.length}개의 작은 약속</small></button><button class="shelf" data-act="pages"><span class="shelf-icon">📚</span><strong>나의 페이지</strong><small>${pages.length}개의 소중한 발견</small></button></div>${heading('곧 만나러 갈 곳','UPCOMING')}${upcoming.map(entry).join('')||empty('다가오는 일정이 없어요.')}<div class="divider"></div>${heading('최근 담은 이야기','RECENT')}${pages.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,4).map(entry).join('')||empty('기억하고 싶은 정보를 담아주세요.')}<div class="footer">어떤 기억이든, 가볍게 담아요.</div>`;}
function pages(){const list=items.filter(i=>i.type==='page').filter(i=>state.filter==='전체'||i.category===state.filter).filter(i=>[i.title,i.category,...i.blocks.map(b=>b.text),i.note||''].join(' ').toLowerCase().includes(state.query.toLowerCase())).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));const cats=['전체',...new Set(items.filter(i=>i.type==='page').map(i=>i.category))];return intro('나의 작은 서랍','좋아하는 정보에 내 생각을 더해요.','📚')+banner()+`<div class="search"><input id="search" aria-label="페이지 검색" placeholder="제목이나 내용으로 찾아보세요" value="${E(state.query)}"></div><div class="filters">${cats.map(c=>`<button data-act="filter" data-filter="${E(c)}" class="${state.filter===c?'active':''}">${E(c)}</button>`).join('')}</div><div id="page-results">${list.map(entry).join('')||empty(state.query?'찾는 내용을 아직 담지 않았어요.':'아직 비어 있는 서랍이에요.')}</div>`;}
function attachments(i){return `<section class="attachments"><div class="attachments-head"><h3>함께 담은 스크린샷 <span class="results-count">${i.attachments.length}</span></h3><button data-act="attach" class="tiny-btn">＋ 추가</button></div><div class="attachments-grid">${i.attachments.map(a=>`<button class="attachment" data-act="image" data-image="${E(a.id)}"><img src="${url(a)}" alt="${E(a.filename)}"><small class="filename">${E(a.filename)}</small><small>첨부 ${stamp(a.addedAt)}</small></button>`).join('')}</div><p class="summary-note">첨부일시는 담아에 넣은 시간이에요. 사진을 촬영한 시간과는 달라요.</p></section>`;}
function detail(){const i=items.find(i=>i.id===state.active);if(!i)return empty();const blocks=i.blocks||[];return `<div class="detail-head"><button class="back" data-act="back">‹ ${i.type==='event'?'캘린더':'나의 페이지'}</button><button data-act="edit">수정</button></div><div class="detail-emoji">${E(i.emoji)}</div><h2 class="detail-title">${E(i.title)}</h2><span class="chip">${E(i.category)}</span>${i.type==='event'?`<div class="meta"><div class="meta-row"><span>날짜</span><span>${dateFull(i.start)}${i.end!==i.start?'<br>~ '+dateFull(i.end):''}</span></div><div class="meta-row"><span>시간</span><span>${E(i.time||'시간 미정')}${i.endTime?' → '+E(i.endTime):''}</span></div><div class="meta-row"><span>장소</span><span>${E(i.location||'장소 미정')}</span></div></div>${i.condition?`<div class="hint warning">${E(i.condition)}</div>`:''}<button class="secondary" data-act="ics">↗ 캘린더 파일로 내보내기</button>`:`<div class="blocks">${blocks.map((b,n)=>`<div class="block block-${b.type} ${b.checked?'checked':''}">${b.type==='check'?`<input type="checkbox" data-check="${n}" aria-label="${E(b.text||'체크 항목')}" ${b.checked?'checked':''}>`:''}<textarea data-block="${n}" aria-label="${b.type==='heading'?'제목 블록':'내용 블록'} ${n+1}" rows="1">${E(b.text)}</textarea><button class="remove-block" data-act="remove-block" data-index="${n}" aria-label="블록 ${n+1} 삭제">×</button></div>`).join('')}</div><div class="block-add">${[['heading','제목'],['text','글'],['bullet','목록'],['check','체크']].map(([t,s])=>`<button data-act="add-block" data-type="${t}">＋ ${s}</button>`).join('')}</div><p class="summary-note">블록과 체크, 메모는 자동으로 저장돼요.</p>`}<div class="note"><label class="field"><span>나의 메모</span><textarea data-note placeholder="내 생각을 조용히 적어두세요.">${E(i.note||'')}</textarea></label></div>${attachments(i)}${i.ocrText?`<details class="ocr-details"><summary>읽어낸 원문 보기</summary><textarea readonly aria-label="저장된 OCR 원문">${E(i.ocrText)}</textarea><p class="summary-note">자동 인식 결과예요. 첨부한 원본과 비교해 확인할 수 있어요.</p></details>`:''}<div class="actions"><button class="secondary danger" data-act="delete">${state.deleteConfirm?'정말 삭제할까요? 한 번 더 눌러주세요.':'기억 삭제'}</button></div>`;}
function importView(){return `<button class="back" data-act="back">‹ 돌아가기</button>${intro('스크린샷을 담아볼까요?','날짜는 일정으로, 이야기는 페이지로.','✨')}<div class="upload-zone" id="drop-zone" role="button" tabindex="0" aria-label="스크린샷 파일 선택"><span class="plus">＋</span><strong>사진을 여기에 놓아주세요</strong><p>PNG · JPG · WEBP · 한 장에 최대 15 MB</p><button class="primary" data-act="choose">스크린샷 선택하기</button></div>${state.files.length?`<div class="import-bar"><span class="results-count">${state.selected.size}장 선택됨 / ${state.files.length}장</span><div><button data-act="select-all">모두 선택</button><button data-act="discard-import">비우기</button></div></div><div class="file-grid">${state.files.map(a=>`<label class="file-card ${state.selected.has(a.id)?'selected':''}"><input type="checkbox" data-file="${a.id}" ${state.selected.has(a.id)?'checked':''} ${state.busy?'disabled':''}><img src="${url(a)}" alt="${E(a.filename)}"><small>${E(a.filename)}</small>${a.failed?'<small class="ocr-failed">글자 인식 실패 · 직접 작성 가능</small>':''}</label>`).join('')}</div>`:''}${state.busy?`<div class="progress-track"><span style="width:${Math.max(2,state.progress)}%"></span></div><p class="progress-label" aria-live="polite">${E(state.progressText)}</p><button class="secondary full" style="margin-top:15px" data-act="cancel-ocr">읽기 취소</button>`:state.files.length?`<div class="hint">선택한 이미지는 한 페이지 또는 대표 일정 하나로 담겨요. 글자는 이 기기에서 읽습니다.</div><button class="primary full" data-act="read" ${state.selected.size?'':'disabled'}>선택한 ${state.selected.size}장 읽고 정리하기</button>`:''}<div class="hint">🔒 원본과 내용은 이 브라우저에 저장돼요.<br>글자 인식을 위해 이미지를 서버에 보내지 않습니다.</div>${!state.files.length?`<div class="divider"></div>${heading('먼저 가볍게 둘러보기')}<button class="secondary full" data-act="sample-import">가상 공연 스크린샷으로 체험하기</button>`:''}`;}
function review(){const d=state.draft;if(!d)return '';return `<button class="back" data-act="review-back">‹ ${d.editId?'수정 취소':'이미지 선택으로'}</button>${intro(d.editId?'기억을 다듬어요':'한 번만 확인해주세요',d.type==='event'?'원문을 보고 대표 일정 하나를 정해요.':'기억할 정보를 블록으로 나눠 담아요.')}<div class="route"><button data-act="route" data-type="event" class="${d.type==='event'?'active':''}">🗓️ 대표 일정</button><button data-act="route" data-type="page" class="${d.type==='page'?'active':''}">📖 한 페이지</button></div>${d.type==='event'&&!d.editId&&d.dates.length?`<section>${heading('원문에서 찾은 날짜','하나만 선택해요')}${d.dates.map((a,n)=>`<label class="candidate ${d.candidate===n?'selected':''}"><input type="radio" name="candidate" data-candidate="${n}" ${d.candidate===n?'checked':''}><span><strong>${E(a.label)} · ${dateFull(a.start)}${a.end!==a.start?' ~ '+dateFull(a.end):''}${a.time?' · '+E(a.time):''}</strong><small>${E(a.context)}</small>${a.yearInferred?'<small>연도가 없어 올해로 제안했어요. 확인이 필요해요.</small>':''}</span></label>`).join('')}</section>`:''}${d.type==='event'&&!d.start?'<div class="hint warning">확실한 날짜를 찾지 못했어요. 날짜를 직접 쓰거나 페이지로 담아주세요.</div>':''}<label class="field"><span>제목</span><input data-draft="title" maxlength="150" value="${E(d.title)}" placeholder="기억의 제목"></label><div class="two-fields"><label class="field"><span>분류</span><input data-draft="category" maxlength="30" value="${E(d.category)}"></label><label class="field"><span>작은 아이콘</span><input data-draft="emoji" maxlength="10" value="${E(d.emoji)}"></label></div>${d.type==='event'?`<div class="two-fields"><label class="field"><span>시작 날짜</span><input type="date" data-draft="start" value="${E(d.start)}" required></label><label class="field"><span>끝 날짜</span><input type="date" data-draft="end" value="${E(d.end)}"></label></div><div class="two-fields"><label class="field"><span>시작 시간</span><input type="time" data-draft="time" value="${E(d.time)}"></label><label class="field"><span>끝 시간</span><input type="time" data-draft="endTime" value="${E(d.endTime)}"></label></div><label class="field"><span>장소</span><input data-draft="location" value="${E(d.location)}" placeholder="화면에 없으면 비워두세요"></label>${d.start&&d.end<today()?'<div class="hint warning">이미 지난 일정이에요. 기록용으로 담을 수 있어요.</div>':''}${d.condition?`<div class="hint warning">${E(d.condition)}</div>`:''}`:`<label class="field"><span>내용 정리</span><textarea data-draft="summary" rows="8">${E(d.summary)}</textarea><small>기기에서 읽은 문장을 정리했어요. 저장 후 제목·글·목록·체크 블록으로 수정할 수 있어요.</small></label>`}<label class="field"><span>나의 메모</span><textarea data-draft="note" rows="2" placeholder="꼭 기억하고 싶은 것">${E(d.note)}</textarea></label>${d.ocrText&&!d.editId?`<details class="ocr-details"><summary>읽은 글 확인 · 오타 수정</summary><textarea data-draft="ocrText" rows="8">${E(d.ocrText)}</textarea><button class="secondary" data-act="reparse">수정한 글로 다시 정리</button><p class="summary-note">인식 결과에 따라 오타나 누락이 있을 수 있어요.</p></details>`:''}<div class="review-sources">${d.attachments.map(a=>`<button data-act="draft-image" data-image="${a.id}" aria-label="${E(a.filename)} 원본 보기"><img class="review-thumb" src="${url(a)}" alt="${E(a.filename)}"></button>`).join('')}</div><p class="summary-note">원본 ${d.attachments.length}장도 함께 저장돼요.</p><label class="check-confirm"><input type="checkbox" data-confirm ${d.confirmed?'checked':''}><span>${d.type==='event'?'날짜·시간·참가 조건을 원문과 비교해 확인했어요.':'읽어낸 내용과 원본 이미지를 확인했어요.'}</span></label><button class="primary full" data-act="save" ${d.confirmed?'':'disabled'}>${d.editId?'수정 내용 저장':d.type==='event'?'대표 일정 하나 담기':'한 페이지로 담기'}</button>`;}
function settings(){return `<button class="back" data-act="back">‹ 돌아가기</button>${intro('담아를 내 방식으로','가볍게 쓰고, 소중한 기억은 따로 보관해요.')}<section class="settings-section"><h3>시작 화면</h3><p>두 화면은 같은 일정과 페이지를 함께 사용해요.</p><div class="mode-switch"><button data-act="mode" data-mode="calendar" class="${state.mode==='calendar'?'active':''}">캘린더 중심</button><button data-act="mode" data-mode="drawer" class="${state.mode==='drawer'?'active':''}">수집함 중심</button></div></section><section class="settings-section"><h3>내 기기에만 저장</h3><p>로그인과 클라우드 동기화 없이 이 브라우저에 저장해요. 브라우저의 사이트 데이터를 지우면 기억도 삭제됩니다.</p><button class="secondary" data-act="persist">기기에 오래 보관 요청</button><p id="storage-info" class="summary-note">저장 공간은 브라우저가 관리해요.</p></section><section class="settings-section"><h3>기억 백업</h3><p>원본 이미지, 첨부일시, 일정과 블록이 함께 담긴 파일을 내려받아요.</p><button class="secondary" data-act="backup">백업 파일 저장</button><button class="secondary" data-act="restore">백업 불러오기</button></section><section class="settings-section"><h3>예시로 둘러보기</h3><p>가상의 전시·공연·책 정보를 넣어 화면을 확인할 수 있어요.</p><button class="secondary" data-act="seed">예시 기억 담기</button><button class="secondary" data-act="clear-samples">예시만 지우기</button></section><section class="settings-section"><h3>이 버전에서 가능한 것</h3><p>기기 내 한국어·영어 글자 인식, 대표 일정 저장, 선택한 이미지 묶기, 블록 메모, 원본 보기, 백업을 지원해요. 웹을 닫은 상태의 자체 알림과 기기 간 동기화는 아직 제공하지 않아요.</p><details><summary class="muted">오픈소스 안내</summary><p>문자인식: Tesseract.js 6.0.1, Tesseract.js-core 6.0.0, tessdata_best 한국어·tessdata_fast 영어 모델. Apache-2.0. <a href="vendor/NOTICE.txt" target="_blank" rel="noopener">라이선스 안내</a></p></details></section><div class="footer">담아 · 첫 번째 웹 버전<br>당신의 작은 기억들을 위한 공간 🌱</div>`;}
function nav(name,label,glyph){return `<button class="${state.view===name?'active':''}" data-act="${name}"><span class="nav-icon" aria-hidden="true">${glyph}</span>${label}</button>`;}
function render(){const screens={calendar,home,pages,detail,import:importView,review,settings};app.innerHTML=`<div class="shell"><aside class="sidebar"><button class="brand" data-act="home"><img src="assets/sprout.svg" alt=""><span><strong>담아</strong><small>LITTLE MEMORIES</small></span></button><nav class="side-nav" aria-label="주 메뉴">${nav('home','나의 수집함','⌂')}${nav('calendar','캘린더','▦')}${nav('pages','나의 페이지','▤')}<button class="add" data-act="import"><span class="nav-icon">＋</span>스크린샷 담기</button>${nav('settings','설정과 백업','⚙')}</nav><div class="side-note"><b>🌿 기기 안에서, 조용히</b>원본과 기억은 이 브라우저에 저장돼요.</div></aside><main class="main"><header class="topbar"><button class="topbar-title" data-act="home">🌱 담아</button><div class="mode-switch" aria-label="화면 구성"><button data-act="mode" data-mode="calendar" class="${state.mode==='calendar'?'active':''}">캘린더 중심</button><button data-act="mode" data-mode="drawer" class="${state.mode==='drawer'?'active':''}">수집함 중심</button></div><button class="tiny-btn" data-act="settings" aria-label="설정과 백업">⚙</button></header>${(screens[state.view]||calendar)()}</main></div><nav class="bottom-nav" aria-label="아래 메뉴">${state.mode==='drawer'?nav('home','수집함','⌂'):''}${nav('calendar','캘린더','▦')}<button class="add" data-act="import" aria-label="스크린샷 담기"><span class="nav-icon">＋</span><small>담기</small></button>${nav('pages','페이지','▤')}</nav>`;resizeBlocks();}
function resizeBlocks(){app.querySelectorAll('.block textarea').forEach(t=>{t.style.height='auto';t.style.height=t.scrollHeight+'px';});}
function current(){return items.find(i=>i.id===state.active);}
async function persist(i){i.updatedAt=new Date().toISOString();await putItem(i);}
function startSave(i){const prior=saveFlights.get(i.id)||Promise.resolve();const flight=prior.catch(()=>{}).then(()=>persist(i));saveFlights.set(i.id,flight);flight.catch(storageError);flight.finally(()=>{if(saveFlights.get(i.id)===flight)saveFlights.delete(i.id);}).catch(()=>{});return flight;}
function queueSave(){const i=current();if(!i)return;const pending=pendingSaves.get(i.id);if(pending)clearTimeout(pending.timer);const timer=setTimeout(()=>{pendingSaves.delete(i.id);startSave(i);},500);pendingSaves.set(i.id,{timer,item:i});}
async function settleSave(id,discard=false){const pending=pendingSaves.get(id);if(pending){clearTimeout(pending.timer);pendingSaves.delete(id);}if(pending&&!discard)await startSave(pending.item);const flight=saveFlights.get(id);if(flight)await flight.catch(()=>{});}
async function settleAllSaves(){await Promise.all([...new Set([...pendingSaves.keys(),...saveFlights.keys()])].map(id=>settleSave(id)));}
function storageError(err){console.error(err);toast('저장하지 못했어요. 저장 공간과 브라우저 설정을 확인해 주세요.');}
function go(view){state.view=view;state.deleteConfirm=false;render();window.scrollTo({top:0});}
function open(i){state.active=i.id;go('detail');}
async function addFiles(files){const allowed=Array.from(files).filter(f=>['image/png','image/jpeg','image/webp'].includes(f.type)&&f.size<=15*1024*1024);if(allowed.length!==files.length)toast('PNG·JPG·WEBP, 한 장 15 MB 이하만 담을 수 있어요.');for(const f of allowed){const a={id:uid(),blob:f,filename:f.name,addedAt:new Date().toISOString(),fileModifiedAt:f.lastModified?new Date(f.lastModified).toISOString():null};state.files.push(a);state.selected.add(a.id);}await setMeta('importQueue',state.files);render();}
async function getWorker(run){if(worker)return worker;const w=await Tesseract.createWorker('kor+eng',1,{workerPath:new URL('vendor/worker.min.js',location.href).href,corePath:new URL('vendor/core/',location.href).href,langPath:new URL('vendor/lang/',location.href).href,cachePath:'dama-kor-best-v1',workerBlobURL:false,logger:m=>{if(!state.busy)return;if(m.status==='recognizing text'){state.progress=(state.ocrIndex+m.progress)/state.ocrCount*100;state.progressText=`${state.ocrIndex+1} / ${state.ocrCount}장 · 글자를 읽고 있어요`;updateProgress();}else if(state.ocrIndex===0){state.progressText='이 기기에서 글자를 읽을 준비를 하고 있어요.';updateProgress();}}});if(run!==ocrRun){await w.terminate();throw new Error('cancelled');}worker=w;return w;}
function updateProgress(){const bar=app.querySelector('.progress-track span'),label=app.querySelector('.progress-label');if(bar)bar.style.width=Math.max(2,state.progress)+'%';if(label)label.textContent=state.progressText;}
async function recognize(){const selected=state.files.filter(a=>state.selected.has(a.id));if(!selected.length)return;const run=++ocrRun;state.busy=true;state.progress=0;state.progressText='기기 안에서 읽기를 준비해요.';state.ocrIndex=0;state.ocrCount=selected.length;render();try{const w=await getWorker(run);for(let n=0;n<selected.length;n++){state.ocrIndex=n;const a=selected[n];if(!a.ocr||a.failed){a.failed=false;try{const r=await readImage(w,a.blob,phase=>{state.progressText=phase;updateProgress();});if(run!==ocrRun)return;a.ocr=r;}catch(e){if(run!==ocrRun)return;a.failed=true;a.ocr={text:'',confidence:0};}}state.progress=(n+1)/selected.length*100;updateProgress();await setMeta('importQueue',state.files);}if(run!==ocrRun)return;state.busy=false;if(selected.every(a=>!a.ocr?.text.trim()))toast('글자를 읽지 못했어요. 원본을 보면서 직접 내용을 적을 수 있어요.');makeDraft(selected);go('review');}catch(e){if(run!==ocrRun)return;state.busy=false;render();toast('글자 인식을 시작하지 못했어요. 잠시 후 다시 시도하거나 직접 정리할 수 있어요.');console.error(e);}}
function makeDraft(attachments,existing=null){const text=attachments.map(a=>a.ocr?.text||'').join('\n\n');const s=suggest(text);const candidate=s.dates[0]||{};state.draft={type:existing?.type|| (s.dates.length?'event':'page'),title:existing?.title||s.title,category:existing?.category||s.category,emoji:existing?.emoji||s.emoji,start:existing?.start||candidate.start||'',end:existing?.end||candidate.end||'',time:existing?.time||candidate.time||'',endTime:existing?.endTime||candidate.endTime||'',location:existing?.location||'',condition:existing?.condition||candidate.condition||'',note:existing?.note||'',summary:existing?.blocks?.map(b=>(b.type==='heading'?'# ':b.type==='bullet'?'- ':b.type==='check'?(b.checked?'[x] ':'[ ] '):'')+b.text).join('\n')||s.blocks.map(b=>(b.type==='heading'?'# ':'')+b.text).join('\n'),ocrText:existing?.ocrText||s.text,attachments,dates:s.dates,candidate:0,confirmed:false,editId:existing?.id||null};}
function readDraft(){app.querySelectorAll('[data-draft]').forEach(el=>state.draft[el.dataset.draft]=el.value);}
function parseBlocks(summary){return summary.split('\n').map(s=>s.trim()).filter(Boolean).map(s=>s.startsWith('# ')?{type:'heading',text:s.slice(2),checked:false}:/^\[[ xX]\] /.test(s)?{type:'check',text:s.slice(4),checked:/^\[[xX]\]/.test(s)}:s.startsWith('- ')?{type:'bullet',text:s.slice(2),checked:false}:{type:'text',text:s,checked:false});}
async function saveDraft(){readDraft();const d=state.draft;if(!d.confirmed)return;if(!d.title.trim()){toast('제목을 적어주세요.');return;}if(d.type==='event'&&!d.start){toast('대표 일정의 날짜를 확인해주세요.');return;}if(d.type==='event'&&d.end&&d.end<d.start){toast('끝 날짜는 시작 날짜 이후여야 해요.');return;}if(d.type==='event'&&d.time&&d.endTime&&(!d.end||d.end===d.start)&&d.endTime<d.time){toast('끝 시간을 시작 시간 이후로 확인해주세요.');return;}const at=new Date().toISOString();const old=items.find(i=>i.id===d.editId);const i={id:old?.id||uid(),type:d.type,title:d.title.trim(),category:d.category||'정보',emoji:d.emoji||'📎',start:d.start,end:d.end||d.start,time:d.time,endTime:d.endTime,location:d.location,condition:d.condition,note:d.note,blocks:parseBlocks(d.summary),ocrText:d.ocrText,attachments:d.attachments,createdAt:old?.createdAt||at,updatedAt:at};try{if(d.editId)await settleSave(d.editId);await putItem(i);items=old?items.map(q=>q.id===i.id?i:q):[i,...items];const saved=new Set(d.attachments.map(a=>a.id));state.files=state.files.filter(a=>!saved.has(a.id));state.selected=new Set(state.files.map(a=>a.id));await setMeta('importQueue',state.files);state.draft=null;if(!state.files.length&&worker){await worker.terminate();worker=null;}if(i.type==='event'){state.month=i.start.slice(0,7);state.day=i.start;}open(i);toast(i.type==='event'?'대표 일정 하나를 담았어요.':'선택한 이미지를 한 페이지로 담았어요.');}catch(e){storageError(e);}}
async function seed(){if(items.some(i=>i.sample)){toast('예시가 이미 담겨 있어요.');return;}const at=new Date().toISOString();const examples=[{type:'event',title:'가을의 조각들',category:'전시',emoji:'🖼️',start:'2026-10-14',end:'2026-11-08',time:'10:00',endTime:'18:00',location:'모아 갤러리 · 서울',file:'dama-exhibition.png'},{type:'event',title:'오후의 작은 음악회',category:'공연',emoji:'🎵',start:'2026-10-17',end:'2026-10-17',time:'19:00',endTime:'',location:'소담 아트홀 · 서울',file:'dama-concert.png'},{type:'page',title:'다음에 읽고 싶은 책',category:'책',emoji:'📖',file:'dama-book.png',blocks:[{type:'heading',text:'읽고 싶은 마음',checked:false},{type:'text',text:'천천히 읽으며 마음에 남는 문장을 모아보기.',checked:false},{type:'check',text:'도서관에서 찾아보기',checked:false}]},{type:'page',title:'작은 공간의 정리 아이디어',category:'정보',emoji:'🧺',file:'dama-info.png',blocks:[{type:'heading',text:'한 칸씩, 천천히',checked:false},{type:'bullet',text:'자주 쓰는 물건은 손이 닿는 곳에.',checked:false},{type:'check',text:'주말에 작은 서랍부터 정리하기',checked:false}]}];for(const q of examples){const blob=await (await fetch('assets/'+q.file)).blob();const i={id:uid(),...q,sample:true,note:'가상의 예시입니다.',blocks:q.blocks||[],createdAt:at,updatedAt:at,attachments:[{id:uid(),filename:q.file,blob,addedAt:at}],ocrText:''};delete i.file;await putItem(i);items.push(i);}state.day='2026-10-17';state.month='2026-10';render();toast('가상의 예시 4개를 담았어요.');}
async function clearSamples(){for(const i of items.filter(i=>i.sample)){await settleSave(i.id,true);await removeItem(i.id);}items=items.filter(i=>!i.sample);render();toast('예시만 지웠어요.');}
function showImage(a){const dialog=document.getElementById('image-viewer');document.getElementById('original').src=url(a);document.getElementById('image-meta').textContent=`${a.filename} · 첨부 ${stamp(a.addedAt)}`;dialog.showModal();}
function download(blob,filename){const link=document.createElement('a'),u=URL.createObjectURL(blob);link.href=u;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(u),10000);}
const blobData=b=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(b);});
async function backup(){try{const copy=await Promise.all(items.map(async i=>({...i,attachments:await Promise.all(i.attachments.map(async a=>{const {blob,...rest}=a;return {...rest,data:await blobData(blob)};}))})));download(new Blob([JSON.stringify({format:'dama-backup',version:1,exportedAt:new Date().toISOString(),items:copy})],{type:'application/json'}),`dama-backup-${today()}.json`);toast('원본을 포함한 백업 파일을 저장해요.');}catch(e){toast('백업 파일을 만들지 못했어요.');console.error(e);}}
async function importBackup(f){if(!f)return;if(f.size>180*1024*1024){toast('백업 파일은 180 MB 이하로 나눠주세요.');return;}try{await settleAllSaves();const v=JSON.parse(await f.text());if(v.format!=='dama-backup'||v.version!==1||!Array.isArray(v.items)||v.items.length>2000)throw Error('format');const clean=[];for(const q of v.items){if(!['event','page'].includes(q.type)||typeof q.title!=='string'||!Array.isArray(q.attachments)||q.attachments.length>200||!Array.isArray(q.blocks))throw Error('record');if(q.type==='event'&&(!validDay(q.start)||!validDay(q.end||q.start)||(q.end||q.start)<q.start))throw Error('date');const attachments=[];for(const a of q.attachments){if(typeof a.data!=='string'||a.data.length>22*1024*1024||!/^data:image\/(png|jpeg|webp);base64,/.test(a.data))throw Error('image');const [header,data]=a.data.split(',');const raw=atob(data),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));attachments.push({id:uid(),filename:String(a.filename||'스크린샷'),blob:new Blob([bytes],{type:header.split(':')[1].split(';')[0]}),addedAt:Number.isNaN(Date.parse(a.addedAt))?new Date().toISOString():a.addedAt,fileModifiedAt:a.fileModifiedAt||null,ocr:a.ocr?{text:String(a.ocr.text||''),confidence:Number(a.ocr.confidence)||0}:undefined});}const importedId=typeof q.id==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(q.id)?q.id:uid();const old=items.find(i=>i.id===importedId);if(old&&old.updatedAt>=q.updatedAt)continue;clean.push({id:importedId,type:q.type,title:q.title.slice(0,150),category:String(q.category||'정보').slice(0,30),emoji:String(q.emoji||'📎').slice(0,10),start:String(q.start||''),end:String(q.end||q.start||''),time:String(q.time||''),endTime:String(q.endTime||''),location:String(q.location||''),condition:String(q.condition||''),note:String(q.note||''),createdAt:Number.isNaN(Date.parse(q.createdAt))?new Date().toISOString():q.createdAt,updatedAt:Number.isNaN(Date.parse(q.updatedAt))?new Date().toISOString():q.updatedAt,sample:!!q.sample,ocrText:String(q.ocrText||''),blocks:q.blocks.filter(b=>['text','heading','bullet','check'].includes(b.type)).map(b=>({type:b.type,text:String(b.text||''),checked:!!b.checked})),attachments});}await putMany(clean);items=await allItems();render();toast(`${clean.length}개의 기억을 불러왔어요. 기존 기억도 함께 보관해요.`);}catch(e){toast('담아에서 만든 올바른 백업 파일인지 확인해주세요.');console.error(e);}}
function ics(){
 const i=current(),escape=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\r\n|\r|\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
 const utc=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
 let dates,timingNote='',allDay=false;
 if(i.time){
  const start=new Date(i.start+'T'+i.time+':00');let end;
  if(i.endTime)end=new Date((i.end||i.start)+'T'+i.endTime+':00');
  else if(i.end&&i.end>i.start){end=new Date(i.end+'T00:00:00');end.setDate(end.getDate()+1);timingNote='종료 시간이 없어 마지막 날짜의 다음 날 00:00까지로 내보냈습니다.';}
  else{end=new Date(start.getTime()+60*60*1000);timingNote='종료 시간이 없어 1시간 길이로 내보냈습니다.';}
  if(Number.isNaN(start.getTime())||Number.isNaN(end.getTime())){toast('날짜와 시간을 확인해주세요.');return;}
  dates='DTSTART:'+utc(start)+'\r\nDTEND:'+utc(end);
 }else{
  allDay=true;
  const end=new Date((i.end||i.start)+'T12:00:00');if(Number.isNaN(end.getTime())){toast('날짜를 확인해주세요.');return;}end.setDate(end.getDate()+1);
  dates='DTSTART;VALUE=DATE:'+i.start.replaceAll('-','')+'\r\nDTEND;VALUE=DATE:'+dayString(end).replaceAll('-','');
 }
 const safeUid=String(i.id).replace(/[^A-Za-z0-9._~-]/g,'_');
 const descriptionParts=[i.note,i.condition,timingNote];
 if(allDay)descriptionParts.push('시간을 입력하지 않은 일정은 종일 일정으로 내보냅니다.');
 const description=descriptionParts.filter(Boolean).join('\n');
 const value=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Dama//Memories//KO','BEGIN:VEVENT','UID:'+safeUid+'@dama','DTSTAMP:'+utc(new Date()),dates,'SUMMARY:'+escape(i.title),'LOCATION:'+escape(i.location),'DESCRIPTION:'+escape(description),'END:VEVENT','END:VCALENDAR'].join('\r\n')+'\r\n';
 download(new Blob([value],{type:'text/calendar;charset=utf-8'}),i.title+'.ics');toast('캘린더 앱에서 열 수 있는 파일을 저장해요.');
}
app.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b)return;const act=b.dataset.act;try{
 if(state.busy&&!['cancel-ocr','draft-image'].includes(act)){toast('읽기를 완료하거나 취소한 후 이동할 수 있어요.');return;}
 if(act==='home')go(state.mode==='drawer'?'home':'calendar');
 else if(['calendar','pages','settings'].includes(act))go(act);
 else if(act==='mode'){state.mode=b.dataset.mode;await setMeta('mode',state.mode);go(state.mode==='drawer'?'home':'calendar');}
 else if(act==='day'){state.day=b.dataset.day;render();}
 else if(act==='month'){const [y,m]=state.month.split('-').map(Number);state.month=dayString(new Date(y,m-1+Number(b.dataset.delta),1)).slice(0,7);render();}
 else if(act==='today'){state.day=today();state.month=state.day.slice(0,7);render();}
 else if(act==='open'){open(items.find(i=>i.id===b.dataset.id));}
 else if(act==='filter'){state.filter=b.dataset.filter;render();}
 else if(act==='back'){if(state.view==='detail'){const i=current();await settleSave(i.id);go(i.type==='event'?'calendar':'pages');}else{state.attachTarget=null;go(state.mode==='drawer'?'home':'calendar');}}
 else if(act==='import'){state.attachTarget=null;go('import');}
 else if(act==='choose')upload.click();
 else if(act==='select-all'){state.selected=new Set(state.files.map(a=>a.id));render();}
 else if(act==='discard-import'){state.files=[];state.selected.clear();await setMeta('importQueue',[]);render();toast('정리 중인 이미지 목록을 비웠어요.');}
 else if(act==='read')await recognize();
 else if(act==='cancel-ocr'){ocrRun++;state.busy=false;if(worker){await worker.terminate();worker=null;}render();toast('읽기를 취소했어요. 선택한 원본은 그대로 있어요.');}
 else if(act==='sample-import'){const blob=await (await fetch('assets/dama-concert.png')).blob();await addFiles([new File([blob],'가상_공연_예시.png',{type:'image/png'})]);}
 else if(act==='route'){readDraft();state.draft.type=b.dataset.type;state.draft.confirmed=false;render();}
 else if(act==='review-back'){if(state.draft?.editId)go('detail');else go('import');}
 else if(act==='reparse'){readDraft();const s=suggest(state.draft.ocrText);state.draft.dates=s.dates;state.draft.summary=s.blocks.map(b=>b.text).join('\n');const c=s.dates[0];if(c)Object.assign(state.draft,{start:c.start,end:c.end,time:c.time,endTime:c.endTime,condition:c.condition,candidate:0});state.draft.confirmed=false;render();}
 else if(act==='save')await saveDraft();
 else if(act==='edit'){await settleSave(current().id);makeDraft(current().attachments,current());go('review');}
 else if(act==='image')showImage(current().attachments.find(a=>a.id===b.dataset.image));
 else if(act==='draft-image')showImage(state.draft.attachments.find(a=>a.id===b.dataset.image));
 else if(act==='attach'){state.attachTarget=state.active;upload.click();}
 else if(act==='add-block'){current().blocks.push({type:b.dataset.type,text:'',checked:false});await persist(current());render();app.querySelector('.block:last-child textarea')?.focus();}
 else if(act==='remove-block'){current().blocks.splice(Number(b.dataset.index),1);await persist(current());render();}
 else if(act==='delete'){if(!state.deleteConfirm){state.deleteConfirm=true;render();}else{const i=current();await settleSave(i.id,true);await removeItem(i.id);items=items.filter(q=>q.id!==i.id);go(i.type==='event'?'calendar':'pages');toast('기억을 삭제했어요.');}}
 else if(act==='ics')ics();
 else if(act==='seed')await seed();
 else if(act==='clear-samples')await clearSamples();
 else if(act==='backup'){await settleAllSaves();await backup();}
 else if(act==='restore')restore.click();
 else if(act==='persist'){const granted=await navigator.storage?.persist?.();toast(granted?'브라우저가 오래 보관 요청을 허용했어요.':'브라우저가 저장 기간을 관리해요. 백업 파일도 보관해주세요.');}
 }catch(err){storageError(err);}});
app.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-block]')){current().blocks[+el.dataset.block].text=el.value;resizeBlocks();queueSave();}else if(el.matches('[data-note]')){current().note=el.value;queueSave();}else if(el.matches('[data-draft]')){state.draft[el.dataset.draft]=el.value;}else if(el.id==='search'){state.query=el.value;const pos=el.selectionStart;render();const s=document.getElementById('search');s.focus();s.setSelectionRange(pos,pos);}});
app.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-file]')){el.checked?state.selected.add(el.dataset.file):state.selected.delete(el.dataset.file);render();}else if(el.matches('[data-confirm]')){state.draft.confirmed=el.checked;readDraft();render();}else if(el.matches('[data-candidate]')){readDraft();const n=+el.dataset.candidate,c=state.draft.dates[n];Object.assign(state.draft,{candidate:n,start:c.start,end:c.end,time:c.time,endTime:c.endTime,condition:c.condition,confirmed:false});render();}else if(el.matches('[data-check]')){current().blocks[+el.dataset.check].checked=el.checked;queueSave();el.closest('.block').classList.toggle('checked',el.checked);}});
upload.addEventListener('change',async()=>{const fs=Array.from(upload.files||[]);upload.value='';if(state.attachTarget){const target=items.find(i=>i.id===state.attachTarget);const allowed=fs.filter(f=>['image/png','image/jpeg','image/webp'].includes(f.type)&&f.size<=15*1024*1024);target.attachments.push(...allowed.map(f=>({id:uid(),blob:f,filename:f.name,addedAt:new Date().toISOString(),fileModifiedAt:f.lastModified?new Date(f.lastModified).toISOString():null})));await persist(target);state.attachTarget=null;render();toast(`${allowed.length}장의 원본을 추가했어요.`);}else await addFiles(fs);});
restore.addEventListener('change',()=>{importBackup(restore.files?.[0]);restore.value='';});
app.addEventListener('keydown',e=>{if(e.target.id==='drop-zone'&&['Enter',' '].includes(e.key)){e.preventDefault();upload.click();}});
app.addEventListener('dragover',e=>{if(state.view==='import'){e.preventDefault();document.getElementById('drop-zone')?.classList.add('dragging');}});
app.addEventListener('dragleave',()=>document.getElementById('drop-zone')?.classList.remove('dragging'));
app.addEventListener('drop',async e=>{if(state.view==='import'){e.preventDefault();if(!state.busy)await addFiles(Array.from(e.dataTransfer.files));}});
document.getElementById('close-viewer').onclick=()=>document.getElementById('image-viewer').close();
document.getElementById('image-viewer').addEventListener('click',e=>{if(e.target.tagName==='DIALOG')e.target.close();});
window.addEventListener('pagehide',()=>{const i=current();if(i&&state.view==='detail')putItem(i);});
async function init(){try{items=await allItems();state.mode=await getMeta('mode')||'calendar';state.view=state.mode==='drawer'?'home':'calendar';state.files=await getMeta('importQueue')||[];state.selected=new Set(state.files.map(a=>a.id));if(state.files.length)state.view='import';render();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(console.error);}catch(e){app.innerHTML='<div class="storage-error">브라우저 저장소를 사용할 수 없어요. 일반 브라우저 창에서 열어주세요.</div>';console.error(e);}}
init();
